    #[test]
    fn test_find_max_in_prefix() {
        let v = [3, 1, 4, 2, 5];
        assert_eq!(find_max_in_prefix(&v, 0), (3, 0));
        assert_eq!(find_max_in_prefix(&v, 2), (4, 2));
        assert_eq!(find_max_in_prefix(&v, 4), (5, 4));
    }

    #[test]
    fn test_find_min_in_suffix() {
        let v = [3, 1, 4, 2, 5];
        assert_eq!(find_min_in_suffix(&v, 4), (5, 4));
        assert_eq!(find_min_in_suffix(&v, 2), (2, 3));
        assert_eq!(find_min_in_suffix(&v, 1), (1, 1));
    }

    #[test]
    fn test_barrier() {
        let v = [1, 2, 3, 4, 5];
        // Every prefix max is less than every suffix min
        assert!(barrier(&v, 0));
        assert!(barrier(&v, 1));
        assert!(barrier(&v, 3));
        // Last index vacuously true
        assert!(barrier(&v, 4));

        let w = [1, 3, 2, 4];
        assert!(barrier(&w, 0)); // 1 < min{3,2,4}
        assert!(!barrier(&w, 1)); // max{1,3}=3 is not < min{2,4}=2
        assert!(barrier(&w, 2)); // max{1,3,2}=3 < 4
    }
